def chk3(items, w=128):
    return table(["", "😀", "🙂", "😕"], [[x, '<span class="chk"></span>', '<span class="chk"></span>', '<span class="chk"></span>'] for x in items], [f"{w}mm", "18mm", "18mm", "18mm"])


def tall(html, h):
    return html.replace("<td></td>", f'<td style="height:{h}mm"></td>')


def echelle(marks=None, w=176):
    """Échelle d'opinion de « pas du tout d'accord » à « tout à fait d'accord » ; marks = {position 0-4: prénom}."""
    labs = ["pas du tout<br>d'accord", "plutôt pas<br>d'accord", "sans<br>avis", "plutôt<br>d'accord", "tout à fait<br>d'accord"]
    cols = ["#E4572E", "#F29E4C", "#9aa1b1", "#7CB66B", "#2BA88F"]
    emo = ["😠", "🙁", "😐", "🙂", "😀"]
    cells = ""
    for i in range(5):
        who = (marks or {}).get(i, "")
        cells += (f'<div style="flex:1;text-align:center"><div style="height:7mm;background:{cols[i]};{"border-radius:3.5mm 0 0 3.5mm;" if i == 0 else ""}{"border-radius:0 3.5mm 3.5mm 0;" if i == 4 else ""}display:flex;align-items:center;justify-content:center;font-size:13pt">{emo[i]}</div>'
                  f'<div class="xs" style="line-height:1.15;margin-top:1mm">{labs[i]}</div>' + (f'<div class="xs" style="color:{MC};font-weight:700">▲ {who}</div>' if who else "") + '</div>')
    return f'<div style="display:flex;gap:1mm;width:{w}mm;max-width:100%">{cells}</div>'


def balance(pour=(), contre=(), w=176):
    """Balance des arguments : plateau POUR à gauche, CONTRE à droite (listes vides = à compléter)."""
    def plateau(t, items, col):
        li = "".join(f'<div class="xs" style="border-bottom:1px dashed #c9ced8;padding:.8mm 0;min-height:6mm">{x}</div>' for x in (items or [""] * 4))
        return f'<div style="flex:1;border:2px solid {col};border-radius:3mm;padding:1.5mm 2.5mm;background:#fff"><b style="color:{col}">{t}</b>{li}</div>'
    svg = (f'<svg viewBox="0 0 200 34" width="100%" style="display:block"><polygon points="94,34 106,34 100,22" fill="#1F2A44"/><line x1="100" y1="22" x2="100" y2="8" stroke="#1F2A44" stroke-width="2"/>'
           f'<line x1="22" y1="10" x2="178" y2="6" stroke="#1F2A44" stroke-width="2.4"/><circle cx="100" cy="8" r="3" fill="{MC}"/>'
           f'<line x1="22" y1="10" x2="22" y2="32" stroke="#9aa1b1"/><line x1="178" y1="6" x2="178" y2="32" stroke="#9aa1b1"/></svg>')
    return f'<div style="width:{w}mm;max-width:100%">{svg}<div class="flex top" style="gap:3mm;align-items:stretch">{plateau("👍 POUR", pour, "#2BA88F")}{plateau("👎 CONTRE", contre, "#E4572E")}</div></div>'


def burger(rows=None, quiz=False):
    """Le paragraphe argumentatif en couches (connecteur, argument, explication, exemple, petite conclusion)."""
    layers = [("① Connecteur", "D'abord, / De plus, / Enfin,", "#E9B44C", "6mm 6mm 1.5mm 1.5mm"), ("② Argument", "la raison qui défend ma thèse", "#7CB66B", "1.5mm"),
              ("③ Explication", "pourquoi c'est vrai, comment ça marche", "#D1495B", "1.5mm"), ("④ Exemple", "un fait concret, un chiffre, une expérience", "#F29E4C", "1.5mm"),
              ("⑤ Mini-conclusion", "je reviens à ma thèse", "#C98B4E", "1.5mm 1.5mm 6mm 6mm")]
    out = ""
    for i, (t, d, c, r) in enumerate(layers):
        txt = (rows[i] if rows else ("…………………………………………………………" if quiz else d))
        out += f'<div style="background:{c};border-radius:{r};padding:1.6mm 4mm;margin-bottom:1mm;display:flex;gap:3mm;align-items:center"><b style="min-width:32mm;color:#1F2A44">{t}</b><span class="sm">{txt}</span></div>'
    return f'<div>{out}</div>'


def salle(w=170):
    """Plan d'un débat organisé."""
    def tab(x, y, ww, t, col, n):
        ch = "".join(f'<circle cx="{x + (k + .5) * ww / n}" cy="{y + 21}" r="4.5" fill="{col}"/>' for k in range(n))
        return f'<rect x="{x}" y="{y}" width="{ww}" height="14" rx="3" fill="#fff" stroke="{col}" stroke-width="2"/><text x="{x + ww / 2}" y="{y + 9.5}" font-size="7" text-anchor="middle" font-weight="700">{t}</text>{ch}'
    pub = "".join(f'<circle cx="{40 + k * 15}" cy="{122 + r * 11}" r="4" fill="#cfd4dc"/>' for k in range(9) for r in range(2))
    return (f'<svg viewBox="0 0 200 150" width="{w}mm" style="max-width:100%" font-family="Poppins" fill="#1F2A44">'
            f'<rect x="1" y="1" width="198" height="148" rx="6" fill="{TINT}" stroke="#e0d3bd"/>'
            + tab(75, 10, 50, "🎙️ MODÉRATEUR", MC, 1) + tab(10, 50, 55, "ÉQUIPE POUR", "#2BA88F", 3) + tab(135, 50, 55, "ÉQUIPE CONTRE", "#E4572E", 3)
            + tab(80, 70, 40, "⏱️ TEMPS", "#4A7BD1", 1) + tab(152, 12, 40, "📝 SECRÉTAIRE", "#9B5DE5", 1)
            + f'<text x="100" y="112" font-size="7" text-anchor="middle" font-weight="700">LE PUBLIC = LE JURY (grille d\'observation)</text>{pub}</svg>')


def journal(nom, sous, date):
    return (f'<div style="border-bottom:3px double #1F2A44;margin-bottom:1.5mm;display:flex;justify-content:space-between;align-items:flex-end">'
            f'<span style="font-family:\'DejaVu Serif\';font-size:17pt;font-weight:800;letter-spacing:.5px">{nom}</span><span class="xs muted" style="text-align:right">{sous}<br>{date}</span></div>')


